INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (365746, 15358, 'The Economic Times', 'en', 'Dollar feeble as rate hike bets dwindle, Iran war worries grow', 'https://economictimes.indiatimes.com/markets/forex/forex-news/dollar-feeble-as-rate-hike-bets-dwindle-iran-war-worries-grow/articleshow/133309496.cms', 'The U.S. dollar weakened against major currencies as traders scaled back tightening expectations. Soft economic data, including retail sales and job losses, influenced these shifts. Traders now see a lower chance of a Federal Reserve rate hike in September. Elevated oil prices and geopolitical tensions in the Middle East are causing market fragility. Bond yields globally are rising due to concerns over debt and fiscal discipline.', 'https://img.etimg.com/photo/msid-133309496,imgsize-115796.cms', '2026-08-18T02:08:00+00:00', '2026-08-18T03:08:38.774964'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (365753, 15358, 'The Economic Times', 'en', 'Oil climbs as fading US-Iran peace hopes raise supply risks', 'https://economictimes.indiatimes.com/markets/commodities/news/oil-climbs-as-fading-us-iran-peace-hopes-raise-supply-risks/articleshow/133309237.cms', 'Oil prices climbed as Middle East war peace talks stalled significantly. Iran announced a shift to a fully offensive military posture. The United States ruled out extending a temporary ceasefire agreement. Shipping through the Strait of Hormuz has drastically decreased following recent attacks. This situation heightens worries about global energy supply stability.', 'https://img.etimg.com/photo/msid-133309237,imgsize-49946.cms', '2026-08-18T01:43:28+00:00', '2026-08-18T03:08:38.846519'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (365758, 15358, 'The Economic Times', 'en', 'Global Market Today: Asian shares advance; oil rises on Middle East concerns', 'https://economictimes.indiatimes.com/markets/us-stocks/news/global-market-today-asian-shares-advance-oil-rises-on-middle-east-concerns/articleshow/133308986.cms', 'As peace prospects in the Middle East worsen, oil prices surged, reigniting fears about supply disruptions. Concurrently, US Treasury yields climbed to their highest levels in years, revealing investor anxiety over increased government expenditure. Asian markets showed positive movement, particularly in the tech sector, as chipmakers benefited from growing AI optimism.', 'https://img.etimg.com/photo/msid-133308986,imgsize-150312.cms', '2026-08-18T00:52:33+00:00', '2026-08-18T03:08:38.899158'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
