INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (369118, 15407, 'The Times of India', 'en', 'Clean chit to Champat Rai? SIT submits Ayodhya temple theft report', 'https://timesofindia.indiatimes.com/city/lucknow/clean-chit-to-champat-rai-anil-mishra-sit-final-report-submitted-in-ayodhya-temple-donation-theft-case/articleshow/133312174.cms', 'The Uttar Pradesh home department has submitted the SIT''s final report on the Ayodhya temple donation theft. This report was handed over to the Shri Ram Janmabhoomi Teerth Kshetra Trust for further action. A three-member SIT, formed at the Trust''s request, conducted the investigation. The preliminary report led to an FIR naming eight individuals as accused. The SIT''s findings also guided subsequent arrest actions in the case.', 'https://static.toiimg.com/photo/msid-133312925,imgsize-177259.cms', '2026-08-18T05:28:25+00:00', '2026-08-18T06:39:27.363934'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
