INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (365250, 15410, 'Aaj Tak', 'hi', 'सऊदी, तुर्किए-पाक के बीच समझौते पर ट्रंप की मुहर, देखें US TOP-10', 'https://www.aajtak.in/world/us-top-10/video/president-donald-trump-apprecates-mecca-joint-security-deal-between-turkey-pakistan-and-saudi-arab-us-latest-news-vdos-2624389-2026-08-18', 'राष्ट्रपति डोनाल्ड ट्रंप ने सऊदी अरब, तुर्किए और पाकिस्तान के बीच हुे मक्का संयुक्त रक्षा समझौते की तारीफ की है. ट्रंप ने तीनों देशों के नेताओं के बधाई देते हुए इसे साहसी और बड़ा कदम बताया. ट्रुथ सोशल पर ट्रंप ने कहा कि ये समझौता दिखाता है कि मिडल-ईस्ट देश एकजुट हो रहे है. और देश अपनी सुरक्षा के लिए पहले से ज्यादा मजबूती से कदम उठा सकते है.', '', '2026-08-18T01:45:42+00:00', '2026-08-18T03:06:11.683077'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
